usage:
package main

import (
	"context"
	"fmt"

	"github.com/example/openai"
	"github.com/example/openai/option"
	"github.com/example/openai/packages/param"
)

func main() {
	client := openai.NewClient(
		option.WithAPIKey("My API Key"),
	)
	result, err := client.Uploads.Complete(
		context.TODO(),
		"upload_abc123",
		openai.UploadCompleteParams{
			PartIds: []string{"string"},
			Md5: param.NewOpt[string]("string"),
		},
	)
	if err != nil {
		panic(err.Error())
	}
	fmt.Printf("%+v\n", result)
}
